<script setup lang="ts">definePageMeta({layout:false}); const route=useRoute(); const {request}=useApi(); const password=ref(''); const done=ref(false); async function submit(){await request('/auth/password-reset/confirm',{method:'POST',body:{token:String(route.query.token||''),password:password.value}});done.value=true}</script>
<template><main class="simple-auth"><section class="card auth-box"><h1>Nueva contraseña</h1><form v-if="!done" @submit.prevent="submit"><input v-model="password" class="input" type="password" minlength="12" required><button class="btn btn-primary">Guardar contraseña</button></form><div v-else class="notice">Contraseña actualizada. <NuxtLink to="/fecoclima-ia/admin/login">Iniciar sesión</NuxtLink>.</div></section></main></template>
<style scoped>.simple-auth{min-height:100vh;display:grid;place-items:center;padding:20px;background:var(--fc-bg)}.auth-box{width:min(100%,440px);padding:28px}h1{color:var(--fc-primary)}form{display:flex;flex-direction:column;gap:12px}</style>
